        };
        public static string Expected(string code,string key) => Content[code].Split('|')[Array.IndexOf(Keys,key)];
        [MenuItem("Oceanarium Fishing/Update UI Translations")]
        public static void Apply()
        {
            foreach(string code in LanguageService.Codes)
            {
                var values=Content[code].Split('|');
                if(values.Length!=Keys.Length)throw new InvalidOperationException("Translation entry count: "+code);
                var table=AssetDatabase.LoadAssetAtPath<StringTable>(FoundationBuilder.Root+"/Localization/Tables/OF_UI_"+code+".asset");
                if(table==null)throw new InvalidOperationException("Missing UI table: "+code);
                for(int i=0;i<Keys.Length;i++)table.AddEntry(Keys[i],values[i]);
                for(int i=0;i<Names.Length;i++)table.AddEntry("locale."+LanguageService.Codes[i],Names[i]);
                EditorUtility.SetDirty(table);EditorUtility.SetDirty(table.SharedData);
            }
            AssetDatabase.SaveAssets();
        }
    }
